<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted, nextTick, toRaw } from 'vue';
import Icon from './Icon.vue';
import AnalyticsOverview from './AnalyticsOverview.vue';
import IntelligenceSettings from './IntelligenceSettings.vue';
import CloudDraft from './CloudDraft.vue';
import WidgetStudio from './WidgetStudio.vue';
import SahdevOrb from './SahdevOrb.vue';
import '../styles/dashboard.css';
import MasterConsole from './MasterConsole.vue';import BillingPanel from './BillingPanel.vue';
import Modal from './ui/Modal.vue';
import Toggle from './ui/Toggle.vue';
import Attachment from './Attachment.vue';import AttachmentUpload from './AttachmentUpload.vue';
import { configuration, api, bootstrap, initials, relative, login, logout } from '../lib/api';
import type { Bootstrap, Conversation, Article, Workspace } from '../lib/model';
const state=ref<Bootstrap>();const error=ref('');const toast=ref('');const busy=ref(false);const page=ref('overview');const sidebar=ref(false);
const theme=ref('light');const query=ref('');const filter=ref('all');const activeId=ref('');const ticketOpened=ref(false);const draft=ref('');const replyKind=ref<'reply'|'note'>('reply');
const modal=ref('');const form=ref<Record<string,any>>({});const articleId=ref('');const formError=ref('');const searchOpen=ref(false);const search=ref('');
const settings=ref<Workspace['settings']>();const knowledgeQuery=ref('');const suggestions=ref<{id:string;title:string;excerpt:string;audience:string}[]>([]);const searched=ref(false);const period=ref('24');
const thread=ref<HTMLElement>();let polling:ReturnType<typeof setInterval>;let toastTimer:ReturnType<typeof setTimeout>;
const w=computed(()=>state.value?.workspace);const isAdmin=computed(()=>['owner','admin'].includes(state.value?.session.role||''));const canReply=computed(()=>['owner','admin','agent'].includes(state.value?.session.role||''));
const nav=[{id:'overview',name:'Analytics',icon:'chart'},{id:'inbox',name:'Shared inbox',icon:'inbox'},{id:'tickets',name:'Support tickets',icon:'file'},{id:'customers',name:'Customers',icon:'users'},{id:'knowledge',name:'Knowledge base',icon:'book'},{id:'ai',name:'AI workspace',icon:'sparkles'},{id:'assistant',name:'Assistant settings',icon:'sparkles'},{id:'memory',name:'Customer memory',icon:'users'},{id:'sources',name:'Data & sources',icon:'globe'},{id:'widget',name:'Widget studio',icon:'chat'},{id:'team',name:'Team & access',icon:'shield'},{id:'automation',name:'Workflows',icon:'workflow'},{id:'billing',name:'Billing & plans',icon:'card'},{id:'settings',name:'Settings',icon:'settings'}];
const title=computed(()=>nav.find(n=>n.id===page.value)?.name||(page.value==='master'?'Master console':page.value==='reports'?'Analytics':'Activity log'));
const all=computed(()=>w.value?.conversations||[]);const open=computed(()=>all.value.filter(c=>c.status==='open'));const unresolved=computed(()=>all.value.filter(c=>c.status!=='resolved'));const resolved=computed(()=>all.value.filter(c=>c.status==='resolved'));
const contacts=computed(()=>w.value?.contacts||[]);const current=computed(()=>all.value.find(c=>c.id===activeId.value));
const person=(id:string)=>contacts.value.find(c=>c.id===id)||{name:'Unknown customer',email:'',company:'',plan:'',color:'mint'};
const filtered=computed(()=>all.value.filter(c=>(filter.value==='all'||c.status===filter.value||filter.value==='mine'&&c.assignee===state.value?.session.name||filter.value==='unassigned'&&!c.assignee)&&(!query.value||`${c.subject} ${person(c.contactId).name} ${c.id}`.toLowerCase().includes(query.value.toLowerCase()))).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)));
const tickets=computed(()=>filtered.value.filter(c=>c.channel!=='chat'));
const displayedContacts=computed(()=>contacts.value.filter(c=>`${c.name} ${c.email} ${c.company}`.toLowerCase().includes(query.value.toLowerCase())));
const displayedArticles=computed(()=>(w.value?.articles||[]).filter(a=>`${a.title} ${a.category} ${a.body}`.toLowerCase().includes(query.value.toLowerCase())&&(filter.value==='all'||a.audience===filter.value||a.status===filter.value)));
const avgReply=computed(()=>{const values=all.value.flatMap(c=>{const first=c.messages.find(m=>m.kind==='reply');return first?[Math.max(0,(Date.parse(first.at)-Date.parse(c.createdAt))/60000)]:[];});return values.length?Math.round(values.reduce((a,b)=>a+b,0)/values.length)+'m':'—';});
const sla=(c:Conversation)=>{if(c.messages.some(m=>m.kind==='reply'))return {text:'Replied',class:'good'};if(c.status==='resolved')return {text:'Resolved',class:'good'};const mins=(w.value?.settings.slaMinutes||60)-(Date.now()-Date.parse(c.createdAt))/60000;return {text:mins<0?`${Math.abs(Math.ceil(mins))}m overdue`:`${Math.ceil(mins)}m left`,class:mins<0?'danger':'muted'};};
const breaches=computed(()=>unresolved.value.filter(c=>sla(c).class==='danger').length);
const bars=computed(()=>Array.from({length:12},(_,i)=>{const interval=Number(period.value)*3600000/12;const start=Date.now()-(12-i)*interval;return {label:new Date(start).toLocaleTimeString('en-US',{hour:'numeric',hour12:false}),value:all.value.filter(c=>Date.parse(c.createdAt)>=start&&Date.parse(c.createdAt)<start+interval).length};}));
const barMax=computed(()=>Math.max(2,...bars.value.map(b=>b.value)));const periodCount=computed(()=>bars.value.reduce((n,b)=>n+b.value,0));
const channels=computed(()=>['chat','email','portal'].map(channel=>({channel,count:all.value.filter(c=>c.channel===channel).length})));
const resolutionRate=computed(()=>all.value.length?Math.round(resolved.value.length/all.value.length*100):0);
const searchResults=computed(()=>search.value.trim()?all.value.filter(c=>`${c.subject} ${person(c.contactId).name}`.toLowerCase().includes(search.value.toLowerCase())).slice(0,7):all.value.slice(0,5));
function notify(message:string){toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',4500);}
function go(id:string){page.value=id;query.value='';filter.value='all';sidebar.value=false;ticketOpened.value=false;location.hash=id;}
function view(c:Conversation){activeId.value=c.id;ticketOpened.value=true;page.value=c.channel==='chat'?'inbox':'tickets';draft.value='';suggestions.value=[];searched.value=false;searchOpen.value=false;nextTick(scrollThread);}
function scrollThread(){thread.value?.scrollTo({top:thread.value.scrollHeight,behavior:'smooth'});}
async function load(initial=false){try{const ws=state.value?.workspace.id||localStorage.getItem('sahdev-workspace')||undefined;state.value=await bootstrap(ws);error.value='';if(initial||!settings.value)settings.value=structuredClone(toRaw(state.value.workspace.settings));if(!activeId.value)activeId.value=state.value.workspace.conversations[0]?.id||'';if(state.value.session.role==='client'){location.assign('/portal/');return;}}catch(e:any){if(e.status===403&&!state.value&&localStorage.getItem('sahdev-workspace')){localStorage.removeItem('sahdev-workspace');return load(initial);}error.value=e.message;}}
async function changeWorkspace(id:string){try{state.value=await bootstrap(id);localStorage.setItem('sahdev-workspace',id);settings.value=structuredClone(toRaw(state.value.workspace.settings));activeId.value=state.value.workspace.conversations[0]?.id||'';go('overview');notify('Workspace switched');}catch(e:any){notify(e.message);}}
async function mutation(path:string,method:string,body:unknown){if(!state.value)return;busy.value=true;try{const result=await api(path,{method,body,workspace:w.value!.id,version:state.value.version});await load();return result;}catch(e:any){if(e.status===409)await load();throw e;}finally{busy.value=false;}}
async function updateConversation(c:Conversation,values:Record<string,string>){try{await mutation('/conversations/'+c.id,'PATCH',values);notify(values.status==='resolved'?'Conversation resolved':'Conversation updated');}catch(e:any){notify(e.message);}}
async function send(){if(!current.value||!draft.value.trim()||busy.value)return;try{await mutation('/conversations/'+current.value.id+'/messages','POST',{text:draft.value,kind:replyKind.value});draft.value='';notify(replyKind.value==='note'?'Private note added':'Reply sent');await nextTick();scrollThread();}catch(e:any){notify(e.message);}}
function openModal(type:string,article?:Article){formError.value='';modal.value=type;articleId.value=article?.id||'';if(type==='article')form.value=article?{title:article.title,body:article.body,category:article.category,audience:article.audience,status:article.status}:{title:'',body:'',category:'Getting started',audience:'public',status:'draft'};else if(type==='conversation')form.value={subject:'',text:'',contactId:contacts.value[0]?.id||'',priority:'normal',channel:'portal'};else if(type==='contact')form.value={name:'',email:'',company:'',plan:'Starter'};else if(type==='workspace')form.value={name:''};else if(type==='member')form.value={subject:'',name:'',email:'',role:'agent',contactId:''};}
async function submitForm(){formError.value='';try{if(modal.value==='workspace'){const result=await api('/workspaces',{method:'POST',body:form.value});modal.value='';await changeWorkspace(result.id);return;}
 const path=modal.value==='article'?'/articles'+(articleId.value?'/'+articleId.value:''):modal.value==='contact'?'/contacts':modal.value==='member'?'/members':'/conversations';
 const result=await mutation(path,articleId.value&&modal.value==='article'?'PATCH':'POST',form.value);const type=modal.value;modal.value='';notify(type==='article'?'Knowledge saved':type==='contact'?'Customer added':type==='member'?'Member access granted':'Ticket created');if(type==='conversation'&&result)view(result.result);
 }catch(e:any){formError.value=e.message;}}
async function saveSettings(){try{await mutation('/settings','PATCH',settings.value);notify('Settings saved');}catch(e:any){notify(e.message);}}
async function findKnowledge(text?:string){searched.value=true;try{const result=await api('/suggest?q='+encodeURIComponent(text||knowledgeQuery.value),{workspace:w.value?.id});suggestions.value=result.matches;}catch(e:any){notify(e.message);}}
function insertExcerpt(item:{excerpt:string;audience:string}){draft.value=item.excerpt;replyKind.value=item.audience==='internal'?'note':'reply';notify(item.audience==='internal'?'Internal source inserted as a private note':'Excerpt inserted. Review before sending.');}
async function exportData(){try{const data=await api('/export',{workspace:w.value?.id});const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='sahdev-workspace-export.json';a.click();URL.revokeObjectURL(url);notify('Workspace export downloaded');}catch(e:any){notify(e.message);}}
function toggleTheme(){theme.value=theme.value==='dark'?'light':'dark';document.documentElement.dataset.theme=theme.value;localStorage.setItem('sahdev-theme',theme.value);}
function keys(event:KeyboardEvent){if((event.metaKey||event.ctrlKey)&&event.key==='k'){event.preventDefault();searchOpen.value=!searchOpen.value;}}
onMounted(async()=>{theme.value=document.documentElement.dataset.theme||'light';const hash=location.hash.slice(1);if(nav.some(n=>n.id===hash)||hash==='master')page.value=hash;await load(true);polling=setInterval(()=>{if(!busy.value&&!modal.value)load();},15000);document.addEventListener('keydown',keys);});
onUnmounted(()=>{clearInterval(polling);clearTimeout(toastTimer);document.removeEventListener('keydown',keys);});
</script>

<template>
<div v-if="!state" class="boot-screen"><img src="/favicon.svg" width="48" alt="Sahdev"/><h2>{{error?'Your workspace is waiting':'A little clarity is on its way…'}}</h2><p>{{error||'Loading your conversations and customer context.'}}</p><button v-if="error" class="button primary" @click="login().catch(e=>error=e.message)">Sign in</button></div>
<div v-else class="app-shell">
 <button v-if="sidebar" class="sidebar-scrim" aria-label="Close navigation" @click="sidebar=false"></button>
 <aside class="sidebar" :class="{'mobile-open':sidebar}">
  <a class="brand app-brand" href="/"><img src="/favicon.svg" width="32" alt=""/>sahdev<span class="pill subtle">BUSINESS</span></a>
  <div class="workspace-switch"><div class="workspace-monogram">{{initials(w!.name)}}</div><div><label for="workspace-select">Workspace</label><select id="workspace-select" :value="w!.id" @change="changeWorkspace(($event.target as HTMLSelectElement).value)"><option v-for="workspace in state.workspaces" :key="workspace.id" :value="workspace.id">{{workspace.name}}</option></select></div><button class="icon-button" aria-label="Create workspace" @click="openModal('workspace')"><Icon name="plus" :size="16"/></button></div>
  <div class="nav-label">WORKSPACE</div><nav aria-label="Workspace navigation"><template v-for="(item,i) in nav.filter(n=>!['assistant','memory','sources'].includes(n.id))" :key="item.id"><div v-if="i===6" class="nav-label second">MANAGE</div><button :class="['nav-item',{active:page===item.id||item.id==='ai'&&['assistant','memory','sources'].includes(page)}]" @click="go(item.id)"><Icon :name="item.icon"/><span>{{item.name}}</span><span v-if="item.id==='inbox'&&open.length" class="nav-count">{{open.length}}</span><span v-if="item.id==='ai'" class="mini-badge">LAB</span></button></template><button v-if="state.platformAdmin" :class="['nav-item',{active:page==='master'}]" @click="go('master')"><Icon name="building"/><span>Master console</span></button></nav>
  <div class="sidebar-bottom"><div class="sidebar-tip"><span class="tip-icon"><Icon name="sparkles"/></span><strong>Make every<br/>conversation count.</strong><p>A shared inbox. Smarter context. Your whole team, together.</p><button @click="go('billing')">Explore your plans <Icon name="arrow" :size="15"/></button></div><div class="sidebar-utility"><button @click="toggleTheme" :aria-label="theme==='dark'?'Switch to light theme':'Switch to dark theme'"><Icon :name="theme==='dark'?'sun':'moon'"/><span>{{theme==='dark'?'Light mode':'Dark mode'}}</span></button><a href="/portal/" title="Open customer portal"><Icon name="external"/></a></div><button class="profile" @click="go('team')"><span class="avatar owner">{{initials(state.session.name)}}</span><span><strong>{{state.session.name}}</strong><small>{{state.session.role}} · {{w!.name}}</small></span><Icon name="down" :size="15"/></button></div>
 </aside>
 <div class="app-main">
  <header class="app-topbar"><div><div class="header-page">{{title}}</div><div class="breadcrumb"><button class="icon-button mobile-menu" aria-label="Open navigation" @click="sidebar=true"><Icon name="expand"/></button><span>Dashboard</span><Icon name="right" :size="11"/><strong>{{title}}</strong></div></div><div class="topbar-actions"><button aria-label="Search workspace" class="global-search" @click="searchOpen=true"><Icon name="search" :size="16"/><span>Search anything…</span><kbd>⌘ K</kbd></button><button class="icon-button" aria-label="View activity" @click="go('activity')"><Icon name="bell"/></button><span class="topbar-divider"></span><span class="avatar owner small">{{initials(state.session.name)}}</span></div></header>
  <div v-if="error" class="connection-banner" role="alert">{{error}} <button @click="load()">Try again</button></div>
  <main class="workspace-content" :class="{'inbox-content':page==='inbox'||page==='tickets'&&ticketOpened}">
   <nav v-if="['ai','assistant','memory','sources'].includes(page)" class="intelligence-tabs" aria-label="AI workspace sections"><button v-for="item in [{id:'ai',label:'Workspace',icon:'sparkles'},{id:'assistant',label:'Assistant',icon:'settings'},{id:'memory',label:'Customer memory',icon:'users'},{id:'sources',label:'Data & sources',icon:'globe'},{id:'widget',label:'Chat widget',icon:'chat'}]" :key="item.id" :class="{active:page===item.id}" @click="go(item.id)"><Icon :name="item.icon" :size="15"/>{{item.label}}</button></nav>
   <AnalyticsOverview v-if="page==='overview'||page==='reports'" :state="state" :can-export="isAdmin" @navigate="go" @open="view" @export="exportData"/>

   <template v-else-if="page==='inbox'||page==='tickets'&&ticketOpened">
    <div class="inbox-heading"><div class="flex items-center gap-3"><button v-if="page==='tickets'" class="icon-button" aria-label="Back to ticket list" @click="ticketOpened=false"><Icon name="collapse"/></button><h1>{{page==='tickets'?'Support tickets':'Shared inbox'}}</h1><span class="pill subtle">{{all.length}}</span></div><div class="flex gap-2"><span v-if="w!.sample" class="pill sample">Sample data</span><button v-if="canReply" class="button primary small" @click="openModal('conversation')"><Icon name="plus" :size="16"/>New ticket</button></div></div>
    <div class="inbox-layout"><section class="conversation-list"><div class="list-search"><Icon name="search" :size="16"/><input v-model="query" placeholder="Search conversations" aria-label="Search conversations"/></div><div class="inbox-filters"><select v-model="filter" aria-label="Filter conversations"><option value="all">All conversations</option><option value="open">Open</option><option value="pending">Pending</option><option value="resolved">Resolved</option><option value="mine">Assigned to me</option><option value="unassigned">Unassigned</option></select><Icon name="filter" :size="15"/></div><button v-for="c in filtered" :key="c.id" :class="['conversation-item',{selected:activeId===c.id}]" @click="view(c)"><span :class="['avatar',person(c.contactId).color]">{{initials(person(c.contactId).name)}}<i :class="c.status"></i></span><div><div class="conversation-meta"><strong>{{person(c.contactId).name}}</strong><time>{{relative(c.updatedAt)}}</time></div><h3>{{c.subject}}</h3><p>{{c.messages.at(-1)?.kind==='note'?'Private note: ':''}}{{c.messages.at(-1)?.text}}</p><div class="conversation-labels"><Icon :name="c.channel==='email'?'mail':c.channel==='portal'?'file':'chat'" :size="12"/><span>{{person(c.contactId).company}}</span><span v-if="c.priority==='urgent'" class="urgent-text">Urgent</span></div></div></button><div v-if="!filtered.length" class="empty-state compact"><Icon name="inbox" :size="28"/><p>No conversations match this view.</p></div></section>
    <section v-if="current" class="conversation-main"><header class="thread-heading"><div><h2>{{current.subject}}</h2><p><span class="mono">#{{current.id.slice(0,8).toUpperCase()}}</span> · {{person(current.contactId).name}} · {{current.channel}}</p></div><button v-if="canReply" class="button secondary small" @click="updateConversation(current,{status:current.status==='resolved'?'open':'resolved'})"><Icon :name="current.status==='resolved'?'refresh':'check'" :size="16"/>{{current.status==='resolved'?'Reopen':'Resolve'}}</button></header><div class="thread-timeline" ref="thread"><div class="thread-date">{{new Date(current.createdAt).toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'})}}</div><article v-for="message in current.messages" :key="message.id" :class="['message',message.kind]"><span :class="['avatar small',message.kind==='customer'?person(current.contactId).color:'owner']">{{initials(message.author)}}</span><div class="message-body"><div class="message-byline"><strong>{{message.author}}</strong><span v-if="message.kind==='note'" class="note-label"><Icon name="lock" :size="11"/> Private note</span><time>{{new Date(message.at).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}}</time></div><div class="message-text">{{message.text}}<Attachment v-if="message.attachment" :file="message.attachment" :conversation="current.id" :workspace="w!.id" @error="notify"/></div></div></article><div v-if="current.status==='resolved'" class="resolved-event"><Icon name="checks" :size="15"/> This conversation is resolved.</div></div><CloudDraft v-if="canReply &amp;&amp; configuration.authMode === 'cloud'" :key="w!.id+current.id" :conversation="current" @draft="text=>{draft=text;replyKind='reply'}"/><div v-if="canReply" class="composer" :class="{'note-composer':replyKind==='note'}"><div class="composer-top"><div class="segmented compact"><button :class="{selected:replyKind==='reply'}" @click="replyKind='reply'"><Icon name="chat" :size="14"/>Reply</button><button :class="{selected:replyKind==='note'}" @click="replyKind='note'"><Icon name="lock" :size="14"/>Private note</button></div><button class="text-action" @click="findKnowledge(current.subject+' '+current.messages.filter(m=>m.kind==='customer').at(-1)?.text)"><Icon name="sparkles" :size="15"/>Find an answer</button></div><textarea v-model="draft" :aria-label="replyKind==='note'?'Write a private note':'Write a reply'" :placeholder="replyKind==='note'?'Only your team can see this note…':'A thoughtful reply starts here…'" maxlength="8000" @keydown.ctrl.enter.prevent="send"/><div v-if="suggestions.length" class="inline-sources"><button v-for="source in suggestions" :key="source.id" @click="insertExcerpt(source)"><Icon name="book" :size="14"/>{{source.title}}<span>{{source.audience}}</span><Icon name="plus" :size="14"/></button><small>Source excerpts · review before sending · no model called</small></div><div v-else-if="searched" class="muted text-xs px-3">No published source matched. Ask for more context or reply personally.</div><div class="composer-bottom"><AttachmentUpload :conversation="current.id" :workspace="w!.id" :version="state.version" :kind="replyKind" @uploaded="load();notify('File attached')" @error="notify"/><span><Icon :name="replyKind==='note'?'lock':'shield'" :size="13"/>{{replyKind==='note'?'Visible to the team only':'Visible to this customer'}} <kbd>Ctrl ↵</kbd></span><button :disabled="!draft.trim()||busy" class="button primary small" @click="send">{{busy?'Sending…':replyKind==='note'?'Add note':'Send reply'}}<Icon name="send" :size="14"/></button></div></div><div v-else class="readonly-banner">Your role can read conversations but cannot send replies.</div></section>
    <div v-else class="empty-state"><Icon name="chat" :size="40"/><h2>Every conversation matters.</h2><p>Select a conversation or create a support ticket.</p></div>
    <aside v-if="current" class="context-panel"><h3>Customer context <Icon name="users" :size="15"/></h3><div class="customer-profile"><span :class="['avatar large',person(current.contactId).color]">{{initials(person(current.contactId).name)}}</span><strong>{{person(current.contactId).name}}</strong><span>{{person(current.contactId).email}}</span><span class="pill subtle">{{person(current.contactId).company||'Customer'}}</span></div><div class="context-section"><h4>CONVERSATION DETAILS</h4><label>Status<select :disabled="!canReply" :value="current.status" @change="updateConversation(current,{status:($event.target as HTMLSelectElement).value})"><option value="open">Open</option><option value="pending">Pending</option><option value="resolved">Resolved</option></select></label><label>Priority<select :disabled="!canReply" :value="current.priority" @change="updateConversation(current,{priority:($event.target as HTMLSelectElement).value})"><option value="low">Low</option><option value="normal">Normal</option><option value="high">High</option><option value="urgent">Urgent</option></select></label><label>Assigned to<select :disabled="!canReply" :value="current.assignee" @change="updateConversation(current,{assignee:($event.target as HTMLSelectElement).value})"><option value="">Unassigned</option><option v-for="member in w!.members.filter(m=>['owner','admin','agent'].includes(m.role))" :key="member.id">{{member.name}}</option></select></label></div><div class="context-section"><h4>FIRST RESPONSE</h4><div :class="['sla-detail',sla(current).class]"><Icon name="clock"/>{{sla(current).text}}</div><small class="muted">Target: {{w!.settings.slaMinutes}} minutes</small></div><div class="context-section"><h4>SERVICE CONTEXT</h4><div class="service-context"><Icon name="globe"/><div><strong>{{person(current.contactId).plan||'No plan recorded'}}</strong><small>{{w!.sample?'Sample customer plan':'Manually recorded plan'}}</small></div></div><p class="tiny-note">WHMCS is not connected. No billing or provisioning actions are available.</p></div><div class="context-section"><h4>TAGS</h4><div class="flex gap-2 flex-wrap"><span v-for="tag in current.tags" :key="tag" class="pill subtle">{{tag}}</span><span v-if="!current.tags.length" class="muted text-xs">No tags</span></div></div></aside></div>
   </template>

   <template v-else-if="page==='tickets'">
    <div class="page-heading"><div><div class="greeting">FROM FIRST QUESTION TO ALL SORTED</div><h1>Support, with a conversation.</h1><p>Follow every request through to a thoughtful resolution.</p></div><button v-if="canReply" class="button primary" @click="openModal('conversation')"><Icon name="plus" :size="16"/>Create ticket</button></div><div class="ticket-stats"><div><span>All tickets</span><strong>{{all.filter(c=>c.channel!=='chat').length}}</strong></div><div><span>Open conversations</span><strong>{{open.length}}</strong></div><div><span>Awaiting first reply</span><strong>{{unresolved.filter(c=>!c.messages.some(m=>m.kind==='reply')).length}}</strong></div><div><span>Past response target</span><strong class="danger">{{breaches}}</strong></div></div><section class="panel"><div class="collection-toolbar"><div class="tabs"><button v-for="status in ['all','open','pending','resolved']" :key="status" :class="{active:filter===status}" @click="filter=status">{{status==='all'?'All tickets':status}}</button></div><div class="list-search"><Icon name="search" :size="16"/><input v-model="query" placeholder="Search tickets…" aria-label="Search tickets"/></div></div><div class="table-scroll"><table><thead><tr><th>Ticket / customer</th><th>Status</th><th>Priority</th><th>Assignee</th><th>Updated</th><th></th></tr></thead><tbody><tr v-for="c in tickets" :key="c.id" @click="view(c)" tabindex="0" @keydown.enter="view(c)"><td><strong class="table-subject">{{c.subject}}</strong><small class="muted">#{{c.id.slice(0,8)}} · {{person(c.contactId).name}}</small></td><td><span :class="['status',c.status]">{{c.status}}</span></td><td><span :class="['priority',c.priority]"><i></i>{{c.priority}}</span></td><td>{{c.assignee||'Unassigned'}}</td><td>{{relative(c.updatedAt)}} ago</td><td><Icon name="right" :size="16"/></td></tr><tr v-if="!tickets.length"><td colspan="6" class="table-empty">No tickets in this view. Create one to start a conversation.</td></tr></tbody></table></div></section>
   </template>

   <template v-else-if="page==='customers'"><div class="page-heading"><div><div class="greeting">PEOPLE, NOT JUST PROFILES</div><h1>A little more customer context.</h1><p>Keep the person behind every conversation in view.</p></div><button v-if="canReply" class="button primary" @click="openModal('contact')"><Icon name="plus" :size="16"/>Add customer</button></div><section class="panel"><div class="collection-toolbar"><h2>All customers <span class="pill subtle">{{contacts.length}}</span></h2><div class="list-search"><Icon name="search" :size="16"/><input v-model="query" placeholder="Find a customer…" aria-label="Find a customer"/></div></div><div class="table-scroll"><table><thead><tr><th>Customer</th><th>Company</th><th>Service plan</th><th>Conversations</th><th>Actions</th></tr></thead><tbody><tr v-for="contact in displayedContacts" :key="contact.id"><td><div class="person-cell"><span :class="['avatar',contact.color]">{{initials(contact.name)}}</span><div><strong>{{contact.name}}</strong><small>{{contact.email}}</small></div></div></td><td>{{contact.company||'—'}}</td><td><span class="pill subtle">{{contact.plan||'Not specified'}}</span></td><td>{{all.filter(c=>c.contactId===contact.id).length}}</td><td><button class="text-action" @click="go('inbox');query=contact.name">View conversations <Icon name="arrow" :size="14"/></button></td></tr><tr v-if="!displayedContacts.length"><td colspan="5" class="table-empty">No customers yet. Add a customer to start a conversation.</td></tr></tbody></table></div></section></template>

   <template v-else-if="page==='knowledge'"><div class="page-heading"><div><div class="greeting">YOUR TEAM’S SHARED UNDERSTANDING</div><h1>Good answers start here.</h1><p>Helpful guides for your customers. Trusted playbooks for your team.</p></div><button v-if="isAdmin" class="button primary" @click="openModal('article')"><Icon name="plus" :size="16"/>Create article</button></div><div class="knowledge-summary"><div><Icon name="book"/><strong>{{w!.articles.length}}</strong><span>Total articles</span></div><div><Icon name="globe"/><strong>{{w!.articles.filter(a=>a.audience==='public'&&a.status==='published').length}}</strong><span>Public & published</span></div><div><Icon name="lock"/><strong>{{w!.articles.filter(a=>a.audience==='internal').length}}</strong><span>Team knowledge</span></div></div><div class="collection-toolbar no-border"><div class="tabs"><button v-for="f in ['all','public','internal','draft']" :key="f" :class="{active:filter===f}" @click="filter=f">{{f==='all'?'All knowledge':f}}</button></div><div class="list-search"><Icon name="search" :size="16"/><input v-model="query" placeholder="Search knowledge…" aria-label="Search knowledge"/></div></div><div class="article-grid"><button v-for="article in displayedArticles" :key="article.id" class="article-card" @click="openModal('article',article)"><div class="flex justify-between"><span class="article-icon"><Icon :name="article.audience==='internal'?'lock':'file'" :size="22"/></span><span :class="['status',article.status==='published'?'open':'pending']">{{article.status}}</span></div><small>{{article.category}}</small><h2>{{article.title}}</h2><p>{{article.body}}</p><div class="article-foot"><span><Icon :name="article.audience==='internal'?'lock':'globe'" :size="13"/>{{article.audience==='internal'?'Team only':'Public knowledge'}}</span><span>{{relative(article.updatedAt)}} ago <Icon name="upRight" :size="15"/></span></div></button></div><div v-if="!displayedArticles.length" class="empty-state"><Icon name="book" :size="38"/><h2>Make your first answer reusable.</h2><p>Create a knowledge article for questions your team hears often.</p></div></template>

   <template v-else-if="page==='ai'"><div class="page-heading"><div><div class="greeting">INTELLIGENCE WITH A HUMAN IN THE LOOP</div><h1>Your knowledge, at your side.</h1><p>Find the right source. Keep the final word.</p></div><a v-if="configuration.authMode==='cloud'" href="/dashboard#brands" class="button primary">Test a funded AI model ↗</a><span v-else class="pill sample"><Icon name="shield" :size="14"/>Live AI disabled</span></div><div class="ai-layout"><section class="panel ai-search-panel"><div class="ai-welcome"><div class="ai-orb-stage"><SahdevOrb :size="110" :palette="w!.intelligence?.widget.orbPalette" :motion="w!.intelligence?.widget.orbMotion"/></div><h2>What can we help you answer?</h2><p>Search your published knowledge for a source-backed starting point.</p></div><form class="ai-query" @submit.prevent="findKnowledge()"><Icon name="sparkles"/><input v-model="knowledgeQuery" required placeholder="Ask about domains, invoices, or team permissions…" aria-label="Search published knowledge"/><button class="button primary" aria-label="Search knowledge"><Icon name="arrow"/></button></form><div class="suggestion-chips"><button v-for="q in ['Connect a custom domain','Team roles and access','Find an invoice']" :key="q" @click="knowledgeQuery=q;findKnowledge(q)">{{q}} <Icon name="upRight" :size="13"/></button></div><div v-if="searched" class="knowledge-results"><div class="result-note"><Icon name="book" :size="15"/>Knowledge search · no AI model called</div><article v-for="source in suggestions" :key="source.id" class="source-result"><span class="pill subtle">{{source.audience}} source</span><h3>{{source.title}}</h3><p>{{source.excerpt}}</p><button class="text-action" @click="openModal('article',w!.articles.find(a=>a.id===source.id))">Open original source <Icon name="upRight" :size="14"/></button></article><div v-if="!suggestions.length" class="empty-state compact"><h3>No reliable source found.</h3><p>Try a specific keyword or create a new article. We won’t invent an answer.</p></div></div></section><aside class="ai-aside"><section class="panel"><h3>Assistant readiness</h3><div class="readiness-row"><span><Icon name="check"/>Published knowledge</span><span class="status open">Ready</span></div><div class="readiness-row"><span><Icon name="shield"/>Human review</span><span class="status open">On</span></div><div class="readiness-row"><span><Icon name="sparkles"/>Model provider</span><span class="status pending">Not connected</span></div><p class="tiny-note">Automatic replies and generative suggestions are disabled. Knowledge search uses exact text matching, not embeddings.</p></section><section class="panel"><h3>Usage, without surprises</h3><div class="budget-number">$0.00<span>model spend</span></div><div class="progress-track"><span style="width:0%"></span></div><p class="muted text-xs">Planning budget: ${{w!.settings.monthlyBudget}} / month</p><p class="tiny-note">No provider calls have been made. Budget enforcement is part of the future provider connection.</p></section></aside></div></template>

   <template v-else-if="page==='team'"><div class="page-heading"><div><div class="greeting">THE PEOPLE BEHIND GREAT SUPPORT</div><h1>Your team. Clear responsibilities.</h1><p>Workspace membership and customer access are separate by design.</p></div><button v-if="state.session.role==='owner'" class="button primary" @click="openModal('member')"><Icon name="plus" :size="16"/>Add member</button></div><section class="panel"><div class="table-scroll"><table><thead><tr><th>Team member</th><th>Role</th><th>Access</th><th>Assigned conversations</th></tr></thead><tbody><tr v-for="member in w!.members" :key="member.id"><td><div class="person-cell"><span class="avatar lavender">{{initials(member.name)}}</span><div><strong>{{member.name}}</strong><small>{{member.email}}</small></div></div></td><td><span class="pill subtle">{{member.role}}</span></td><td><span :class="['status',member.status==='sample'?'pending':'open']">{{member.status==='sample'?'Sample profile':'Active'}}</span></td><td>{{all.filter(c=>c.assignee===member.name&&c.status!=='resolved').length}}</td></tr></tbody></table></div></section><div class="role-cards"><article v-for="r in [{name:'Owner',text:'Workspace access, members, exports, and all support settings.'},{name:'Admin',text:'Knowledge, support configuration, and conversation management.'},{name:'Agent',text:'Customer conversations, assignment, private notes, and knowledge search.'},{name:'Viewer',text:'Read the team workspace. No replies or configuration changes.'},{name:'Client',text:'Own conversations and published public articles. No internal notes.'}]" :key="r.name" class="panel"><Icon name="shield"/><h3>{{r.name}}</h3><p>{{r.text}}</p></article></div><p class="muted text-xs">Sample profiles cannot sign in. Real membership requires a verified Auth0 or Sites subject. No invitation emails are sent.</p></template>

   <template v-else-if="page==='settings'||page==='automation'"><div class="page-heading"><div><div class="greeting">MAKE THIS WORKSPACE YOURS</div><h1>{{page==='settings'?'The details make the difference.':'A smoother way to work.'}}</h1><p>{{page==='settings'?'Your team’s identity, preferences, and connected services.':'Simple rules that keep conversations moving.'}}</p></div><button v-if="isAdmin" :disabled="busy" class="button primary" @click="saveSettings"><Icon name="check" :size="16"/>Save changes</button></div><div v-if="settings" class="settings-layout"><section class="panel settings-form"><template v-if="page==='settings'"><h2>Workspace identity</h2><div class="identity-detail"><small>Verified sign-in identity</small><code>{{state.session.subject}}</code><p>Your deployment operator uses this ID to grant platform console access.</p></div><p class="muted">The details customers see when they reach out.</p><label>Support team name<input v-model="settings.replyName" :disabled="!isAdmin" maxlength="60"/></label><label>Welcome message<textarea v-model="settings.welcome" :disabled="!isAdmin" maxlength="500" rows="3"/></label><label>Office hours<input v-model="settings.officeHours" :disabled="!isAdmin" maxlength="100"/></label><label>Accent color<div class="flex items-center gap-3"><input type="color" v-model="settings.accent" :disabled="!isAdmin"/><span class="mono muted">{{settings.accent}}</span></div></label></template><template v-else><h2>Conversation workflows</h2><div class="setting-row"><div><strong>Automatic assignment</strong><p>Assign new conversations to the first available agent or owner in the roster.</p></div><Toggle v-model="settings.autoAssign" label="Automatic assignment" :disabled="!isAdmin"/></div><label>First response target (minutes)<input type="number" min="5" max="10080" v-model.number="settings.slaMinutes" :disabled="!isAdmin"/><small class="muted">Starts when a conversation is created; completes on the first team reply. Uses elapsed time.</small></label><div class="setting-row"><div><strong>Review before sending</strong><p>Knowledge excerpts are inserted into a draft. A person sends the reply.</p></div><span class="status open">Always on</span></div><label>Monthly AI planning budget (USD)<input type="number" min="0" max="10000" v-model.number="settings.monthlyBudget" :disabled="!isAdmin"/><small class="muted">A planning preference while live AI is disabled.</small></label></template></section><aside class="settings-aside"><section class="panel"><h3>Connected services</h3><div class="integration-row"><span class="integration-logo">A</span><div><strong>Auth0</strong><small>Prepared for standalone hosting</small></div><span class="status pending">Setup needed</span></div><div class="integration-row"><span class="integration-logo green">W</span><div><strong>WHMCS</strong><small>Optional service context adapter</small></div><span class="status pending">Not connected</span></div><div class="integration-row"><span class="integration-logo"><Icon name="sparkles"/></span><div><strong>AI provider</strong><small>Connect after validation</small></div><span class="status pending">Disabled</span></div><p class="tiny-note">This Sites deployment uses ChatGPT sign-in. Standalone deployments validate Auth0 access tokens and organization membership.</p></section><section class="panel"><h3>Your data stays portable.</h3><p class="muted text-sm">Export conversations, customers, knowledge, and workspace settings as JSON.</p><button v-if="isAdmin" class="button secondary" @click="exportData"><Icon name="download" :size="16"/>Export workspace</button></section></aside></div></template>

   <WidgetStudio v-else-if="page==='widget'" :state="state" :key="w!.id" @refresh="load()" @conversation="id=>{const c=w!.conversations.find(c=>c.id===id);if(c)view(c);else{activeId=id;go('inbox');load();}}"/><IntelligenceSettings v-else-if="['assistant','memory','sources'].includes(page)" :state="state" :section="page" :key="w!.id+page" @refresh="load()"/><MasterConsole v-else-if="page==='master'"/><BillingPanel v-else-if="page==='billing'" :workspace="w!.id" :sample="w!.sample" :key="w!.id"/><template v-else-if="page==='activity'"><div class="page-heading"><div><div class="greeting">A CLEAR RECORD OF WHAT CHANGED</div><h1>Every action has a story.</h1><p>Recent workspace events. The latest 1,000 events are retained.</p></div></div><section class="panel activity-list"><article v-for="event in w!.audit" :key="event.id"><span class="activity-icon"><Icon :name="event.action.includes('message')?'chat':event.action.includes('article')?'book':'activity'"/></span><div><strong>{{event.detail}}</strong><p>{{event.actor}} <span>· {{event.action}}</span></p></div><time>{{new Date(event.at).toLocaleString('en-IN')}}</time></article></section></template>
  </main>
 </div>
 <div v-if="toast" class="toast" role="status"><Icon name="check" :size="17"/>{{toast}}<button aria-label="Dismiss notification" @click="toast=''"><Icon name="x" :size="15"/></button></div>
 <Modal :open="!!modal" @update:open="!$event&&(modal='')" :title="modal==='article'?(articleId?'Knowledge article':'Create an article'):modal==='contact'?'Meet your next customer':modal==='workspace'?'A fresh workspace':modal==='member'?'Grant workspace access':'Start a support conversation'" :description="modal==='member'?'Use an existing verified identity subject. This grants access immediately; no email is sent.':modal==='conversation'?'A ticket is a conversation with context, ownership, and a clear next step.':undefined"><form class="modal-form" @submit.prevent="submitForm"><template v-if="modal==='article'"><label>Article title<input v-model="form.title" required minlength="3" maxlength="150" :disabled="!isAdmin"/></label><label>Content<textarea v-model="form.body" required maxlength="8000" rows="8" :disabled="!isAdmin"/></label><label>Category<input v-model="form.category" required maxlength="60" :disabled="!isAdmin"/></label><div class="form-row"><label>Audience<select v-model="form.audience" :disabled="!isAdmin"><option value="public">Public · customers & team</option><option value="internal">Internal · team only</option></select></label><label>Status<select v-model="form.status" :disabled="!isAdmin"><option value="draft">Draft</option><option value="published">Published</option></select></label></div></template><template v-else-if="modal==='contact'"><label>Full name<input v-model="form.name" required minlength="2" maxlength="100"/></label><label>Email address<input type="email" v-model="form.email" required maxlength="200"/></label><div class="form-row"><label>Company<input v-model="form.company" maxlength="100"/></label><label>Service plan<input v-model="form.plan" maxlength="60"/></label></div></template><template v-else-if="modal==='workspace'"><label>Workspace name<input v-model="form.name" required minlength="2" maxlength="60" placeholder="e.g. Northstar Hosting"/></label><div class="info-box"><Icon name="shield"/>Your new workspace starts empty and has its own customers, conversations, knowledge, and settings.</div></template><template v-else-if="modal==='member'"><label>Identity subject<input v-model="form.subject" required placeholder="auth0|… or sites:…" maxlength="250"/></label><label>Display name<input v-model="form.name" required maxlength="100"/></label><label>Email<input v-model="form.email" type="email" required/></label><label>Role<select v-model="form.role"><option value="admin">Administrator</option><option value="agent">Agent</option><option value="viewer">Viewer</option><option value="client">Client</option></select></label><label v-if="form.role==='client'">Customer profile<select v-model="form.contactId" required><option value="">Choose a customer</option><option v-for="c in contacts" :key="c.id" :value="c.id">{{c.name}}</option></select></label></template><template v-else><label>Customer<select v-model="form.contactId" required><option value="">Choose a customer</option><option v-for="c in contacts" :key="c.id" :value="c.id">{{c.name}} · {{c.company}}</option></select></label><p v-if="!contacts.length" class="muted text-sm">Add a customer in the Customers section first.</p><label>Subject<input v-model="form.subject" required minlength="3" maxlength="150" placeholder="What can we help with?"/></label><label>Message<textarea v-model="form.text" required rows="5" maxlength="8000" placeholder="Give the conversation a little context…"/></label><div class="form-row"><label>Priority<select v-model="form.priority"><option value="low">Low</option><option value="normal">Normal</option><option value="high">High</option><option value="urgent">Urgent</option></select></label><label>Conversation type<select v-model="form.channel"><option value="portal">Support ticket</option><option value="chat">Live chat</option></select></label></div></template><p v-if="formError" class="form-error" role="alert">{{formError}}</p><div class="modal-actions"><button type="button" class="button secondary" @click="modal=''">{{modal==='article'&&!isAdmin?'Close':'Cancel'}}</button><button v-if="modal!=='article'||isAdmin" :disabled="busy" class="button primary">{{busy?'Saving…':modal==='member'?'Grant access':modal==='article'?'Save article':modal==='conversation'?'Create ticket':modal==='workspace'?'Create workspace':'Add customer'}}<Icon name="arrow" :size="15"/></button></div></form></Modal>
 <Modal :open="searchOpen" @update:open="searchOpen=$event" title="Find a conversation" description="Search across your current workspace."><div class="command-search"><Icon name="search"/><input autofocus v-model="search" placeholder="Search by subject or customer…" aria-label="Search workspace"/></div><div class="command-results"><button v-for="c in searchResults" :key="c.id" @click="view(c)"><Icon :name="c.channel==='chat'?'chat':'file'"/><div><strong>{{c.subject}}</strong><small>{{person(c.contactId).name}} · {{c.status}}</small></div><Icon name="arrow" :size="15"/></button><p v-if="!searchResults.length" class="empty-state compact">No matching conversations.</p></div></Modal>
</div>
</template>
